'use client';
import { useComboboxId, useComboboxIdDispatch } from "./ComboboxIdContext.js";
import { useState } from "react";
import { autoUpdate, flip, offset, size, useDismiss, useFloating, useInteractions, useListNavigation, useRole } from "@floating-ui/react";
import { flushSync } from "react-dom";
//#region src/components/Combobox/useFloatingCombobox.tsx
const useFloatingCombobox = ({ listRef }) => {
	const [open, setOpen] = useState(false);
	const { activeIndex } = useComboboxId();
	const dispatch = useComboboxIdDispatch();
	const { refs, floatingStyles, context } = useFloating({
		open,
		onOpenChange: (newOpen) => {
			if (!newOpen) dispatch?.({
				type: "SET_ACTIVE_INDEX",
				payload: 0
			});
			flushSync(() => {
				if (refs.floating.current && !newOpen) refs.floating.current.scrollTop = 0;
				setTimeout(() => {
					setOpen(newOpen);
				}, 1);
			});
		},
		whileElementsMounted: (reference, floating, update) => {
			autoUpdate(reference, floating, update);
			return () => {
				floating.scrollTop = 0;
			};
		},
		middleware: [
			flip({ padding: 10 }),
			size({ apply({ rects, elements }) {
				requestAnimationFrame(() => {
					Object.assign(elements.floating.style, {
						width: `${rects.reference.width}px`,
						maxHeight: `200px`
					});
				});
			} }),
			offset(10)
		]
	});
	const { getReferenceProps, getFloatingProps, getItemProps } = useInteractions([
		useRole(context, { role: "listbox" }),
		useDismiss(context),
		useListNavigation(context, {
			listRef,
			activeIndex,
			virtual: true,
			scrollItemIntoView: true,
			enabled: open,
			focusItemOnHover: true,
			onNavigate: (index) => {
				dispatch?.({
					type: "SET_ACTIVE_INDEX",
					payload: index || 0
				});
			}
		})
	]);
	return {
		open,
		setOpen,
		activeIndex,
		refs,
		floatingStyles,
		context,
		getReferenceProps,
		getFloatingProps,
		getItemProps
	};
};
//#endregion
export { useFloatingCombobox };
